toolScript:
// --- CALCULATION & FILTER LOGIC ---
        function applySim(type, btn) {
            const viewport = document.getElementById('sim-viewport');
            // UI Switcher Logic
            document.querySelectorAll('.sim-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            // Apply Mathematical Matrix Transformation
            if (type === 'none') {
                viewport.style.filter = 'none';
            } else {
                viewport.style.filter = `url(#${type})`;
            }
        }
        function loadLocalImage(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function (e) {
                    document.getElementById('sim-viewport').src = e.target.result;
                    // Reset Sim to Normal when new image loaded
                    applySim('none', document.querySelector('.sim-btn:first-child'));
                };
                reader.readAsDataURL(input.files[0]);
            }
        }
        // --- GLOBAL UI LOGIC ---
